const j = $input.item.json;

let brut = '';
if (j.from && j.from.value && j.from.value[0]) {
  brut = j.from.value[0].address || '';
} else if (j.From) {
  brut = j.From;
}
const trouve = brut.match(/[\w.+-]+@[\w-]+\.[\w.-]+/);
const expediteur = trouve ? trouve[0].toLowerCase() : '';

const sujet = j.subject || j.Subject || '';
let corps = j.text || j.snippet || '';
corps = corps.split(/\nOn .* wrote:|\nLe .* a écrit/)[0];
corps = corps.substring(0, 6000);

const entetes = j.headers || {};
const auto = String(entetes['auto-submitted'] || '').toLowerCase();
const masse = String(entetes['precedence'] || '').toLowerCase();
const robotEntete = (auto !== '' && auto !== 'no') || masse === 'bulk' || masse === 'junk' || entetes['x-autoreply'] !== undefined;

const moi = String(j.mon_adresse || '').toLowerCase();
const robot = /no-?reply|noreply|mailer-daemon|notification/.test(expediteur);
const ignorer = expediteur === moi || robot || robotEntete || expediteur === '';

const normaliser = (t) => String(t || '')
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9]+/g, ' ')
  .trim();

const motifs = [
  /\bi[gq][nm]or[ez]?[rz]?\s+(tout(es)?\s+)?(les\s+)?(instructions?|consignes?|regles?|directives?)/,
  /\bi[gq][nm]ore?\s+(all\s+)?(previous|prior|above)/,
  /(instructions?|consignes?|directives?)\s+(precedentes?|anterieures?|initiales?|ci dessus)/,
  /\b(ta|ton|votre|tes|vos)\s+(configuration|prompt|system prompt)/,
  /system\s*prompt|prompt\s+systeme/,
  /\b(tu es|vous etes)\s+(maintenant|desormais)/,
  /\byou are now\b/,
  /\b(oublie|oubliez)\s+(tes|vos|toutes|tout)/,
  /\b(revele|reveal|divulgue|montre|affiche)\s+(moi\s+)?(tes|vos|ton|ta|your|the)\s+(instructions|prompt|configuration|consignes|regles)/,
  /developer mode|jailbreak|mode developpeur/
];
const texteBrut = sujet + ' ' + corps;
const texteNormalise = normaliser(texteBrut);
const injection = /<\/?(email|infos)>/i.test(texteBrut) || motifs.some(m => m.test(texteNormalise));

const mots = String(j.mots_sensibles || '')
  .split(',')
  .map(m => m.trim().toLowerCase())
  .filter(m => m !== '');
const texte = texteBrut.toLowerCase();
const sensible = mots.some(m => texte.includes(m));

let decision = 'ia';
let motif = '';
if (ignorer) {
  decision = 'ignorer';
} else if (injection) {
  decision = 'sensible';
  motif = 'injection';
} else if (sensible) {
  decision = 'sensible';
  motif = 'sensible';
}

const masque = (t) => t
  .replace(/[<>]/g, '')
  .replace(/[\w.+-]+@[\w-]+\.[\w.-]+/g, '[email]')
  .replace(/\b[A-Z]{2}\d{2}[A-Z0-9]{10,30}\b/g, '[iban]')
  .replace(/\+?\d[\d\s.-]{7,}\d/g, '[numero]');

return {
  json: {
    id: j.id,
    threadId: j.threadId,
    expediteur: expediteur,
    sujet: sujet,
    sujet_ia: masque(sujet),
    corps_ia: masque(corps),
    decision: decision,
    motif: motif,
    seuil_confiance: j.seuil_confiance,
    envoi_auto_actif: j.envoi_auto_actif,
    nom_organisation: j.nom_organisation,
    base_connaissances: j.base_connaissances
  }
};

const entree = $input.item.json;

let base = entree;
if (entree.decision !== 'sensible') {
  try {
    base = $('Chercher').item.json;
  } catch (e) {
    base = $('Préparer').item.json;
  }
}

if (base.decision === 'sensible') {
  return {
    json: {
      id: base.id,
      threadId: base.threadId,
      expediteur: base.expediteur,
      sujet: base.sujet,
      categorie: base.motif === 'injection' ? 'injection' : 'sensible',
      priorite: 'urgente',
      langue: '',
      sensible: true,
      confiance: 1,
      reponse: '',
      decision: 'sensible'
    }
  };
}

let texte = entree.text || '';
let r = null;
try {
  texte = texte.replace(/```json|```/g, '').trim();
  r = JSON.parse(texte);
} catch (e) {
  r = null;
}

if (!r || typeof r !== 'object') {
  r = { categorie: 'autre', priorite: 'normale', langue: 'fr', sensible: true, confiance: 0, reponse: '' };
}

const categories = ['information', 'reclamation', 'rendez-vous', 'commercial', 'spam', 'autre'];
const priorites = ['urgente', 'normale', 'basse'];
const categorie = categories.includes(r.categorie) ? r.categorie : 'autre';
const priorite = priorites.includes(r.priorite) ? r.priorite : 'normale';
const langue = r.langue === 'en' ? 'en' : 'fr';
let confiance = Number(r.confiance) || 0;
if (confiance < 0) confiance = 0;
if (confiance > 1) confiance = 1;
const sensible = r.sensible === true;
const reponse = typeof r.reponse === 'string' ? r.reponse : '';

const infos = String(base.infos || base.base_connaissances || '');
const trouves = (reponse.match(/[\w.+-]+@[\w-]+\.[\w.-]+|https?:\/\/\S+|www\.\S+|\+?\d[\d\s.-]{7,}\d/g) || [])
  .map(t => t.replace(/[.,;:)]+$/, ''));
const inconnus = trouves.filter(t => !infos.includes(t));
const demandeSecret = /mot de passe|password|code pin|cvv|num[ée]ro de carte|iban/i.test(reponse);
const fuite = /<\/?(email|infos)>|system prompt|mes instructions/i.test(reponse);
const tropLong = reponse.length > 2500;
const reponseRisquee = inconnus.length > 0 || demandeSecret || fuite || tropLong;

let decision = 'valider';
if (categorie === 'spam' || categorie === 'commercial') {
  decision = 'archiver';
} else if (
  !sensible &&
  !reponseRisquee &&
  confiance >= base.seuil_confiance &&
  base.envoi_auto_actif === true &&
  (categorie === 'information' || categorie === 'rendez-vous') &&
  reponse !== ''
) {
  decision = 'auto';
}

if (decision === 'auto') {
  const stock = $getWorkflowStaticData('global');
  const jour = new Date().toISOString().slice(0, 10);
  const cle = jour + '|' + base.expediteur;
  if (!stock.compteurs) {
    stock.compteurs = {};
  }
  Object.keys(stock.compteurs).forEach(k => {
    if (k.indexOf(jour) !== 0) {
      delete stock.compteurs[k];
    }
  });
  stock.compteurs[cle] = (stock.compteurs[cle] || 0) + 1;
  if (stock.compteurs[cle] > 3) {
    decision = 'valider';
  }
}

return {
  json: {
    id: base.id,
    threadId: base.threadId,
    expediteur: base.expediteur,
    sujet: base.sujet,
    categorie: categorie,
    priorite: priorite,
    langue: langue,
    sensible: sensible,
    confiance: confiance,
    reponse: reponse,
    decision: decision
  }
};

const lignes = $input.all().map(i => i.json);
const mails = $('Trier').all(0);

const nettoyer = (t) => String(t || '')
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '');

const sortie = [];

mails.forEach(m => {
  const j = m.json;
  const texte = nettoyer(j.sujet_ia + ' ' + j.corps_ia);

  const notes = lignes.map(l => {
    const mots = String(l.mots_cles || '')
      .split(',')
      .map(x => nettoyer(x).trim())
      .filter(x => x !== '');
    let score = 0;
    mots.forEach(mot => {
      if (mot === '*') {
        score += 0.1;
      } else if (texte.includes(mot)) {
        score += 1;
      }
    });
    return { theme: l.theme, contenu: l.contenu, score: score };
  });

  const retenus = notes
    .filter(n => n.score > 0 && n.contenu)
    .sort((a, b) => b.score - a.score)
    .slice(0, 15);

  let infos = retenus.map(n => n.theme + ' : ' + n.contenu).join('\n');
  if (infos === '') {
    infos = j.base_connaissances || '';
  }
  infos = infos.substring(0, 6000);

  sortie.push({ json: Object.assign({}, j, { infos: infos }) });
});

return sortie;
